// ManifestLoader.swift
// Loads native-benchmark-manifest/v1 plans generated by
// tools/generate-native-plan.mjs. Browser manifests are deliberately rejected
// so paired WebGL2/WebGPU rows cannot be replayed as duplicate native runs.

import Foundation

struct ManifestRunConfig {
    var runNumber: Int
    var suiteId: String
    var runId: String
    var cooldownAfterMs: Double
    var surfaceMode: String
    var instancesList: [Int]
    var trialsPerInstance: Int
    var durationMs: Double
    var warmupMs: Double
    var cooldownMs: Double
    var betweenInstancesMs: Double
    var minFrames: Int
    var layout: String
    var spacing: Float
    var seed: UInt32
    var shuffle: Bool
    var runtimeFamily: String
    var planId: String
    var sourceManifest: String
    var harnessCommit: String
    var harnessVersion: String
    var assetRevision: String
}

struct ManifestFile {
    var schema: String
    var planId: String
    var deviceGroup: String
    var cohortGroup: String
    var runtimeFamily: String
    var api: String
    var mode: String
    var surfaceMode: String
    var rows: [ManifestRunConfig]
}

enum ManifestError: Error, LocalizedError {
    case unsupportedSchema(String)
    case browserManifestRequiresConversion
    case invalidField(String)
    case unsupportedApi(String)
    case unsupportedMode(String)
    case surfaceModeMismatch(String)
    case runCountMismatch(expected: Int, actual: Int)
    case duplicateRunId(String)

    var errorDescription: String? {
        switch self {
        case .unsupportedSchema(let schema):
            return "Unsupported manifest schema: \(schema)"
        case .browserManifestRequiresConversion:
            return "Convert the browser manifest with tools/generate-native-plan.mjs before loading it."
        case .invalidField(let field):
            return "Native plan has an invalid or missing field: \(field)"
        case .unsupportedApi(let api):
            return "This target only supports api=metal, not \(api)."
        case .unsupportedMode(let mode):
            return "This target only supports mode=canvas, not \(mode)."
        case .surfaceModeMismatch(let reason):
            return "Native plan surface-mode mismatch: \(reason)"
        case .runCountMismatch(let expected, let actual):
            return "Native plan declares \(expected) runs but contains \(actual)."
        case .duplicateRunId(let runId):
            return "Native plan contains duplicate run ID \(runId)."
        }
    }
}

func loadNativeManifest(url: URL) throws -> ManifestFile {
    let data = try Data(contentsOf: url)
    guard let json = try JSONSerialization.jsonObject(with: data) as? [String: Any] else {
        throw ManifestError.invalidField("root")
    }

    let schema = string(json, "schema")
    if schema == "webxr-harness-manifest/v1" {
        throw ManifestError.browserManifestRequiresConversion
    }
    guard schema == "native-benchmark-manifest/v1" else {
        throw ManifestError.unsupportedSchema(schema)
    }

    let api = string(json, "api").lowercased()
    guard api == "metal" else { throw ManifestError.unsupportedApi(api) }
    let mode = string(json, "mode").lowercased()
    guard mode == "canvas" else { throw ManifestError.unsupportedMode(mode) }
    let surfaceMode = string(json, "surface_mode").lowercased()
    guard ["flat", "basecolor"].contains(surfaceMode) else {
        throw ManifestError.invalidField("surface_mode")
    }

    let planId = try requiredString(json, "plan_id")
    let deviceGroup = try requiredString(json, "device_group")
    let cohortGroup = try requiredString(json, "cohort_group")
    let runtimeFamily = try requiredString(json, "runtime_family")
    guard runtimeFamily == "native-apple" else {
        throw ManifestError.invalidField("runtime_family")
    }
    let sourceManifest = try requiredString(json, "source_manifest")
    let harnessCommit = string(json, "source_harness_commit")
    let harnessVersion = string(json, "source_harness_version")
    let assetRevision = try requiredString(json, "asset_revision")
    let instances = try intArray(json, "instances")
    let trials = try positiveInt(json, "trials_per_instance")
    let durationMs = try positiveDouble(json, "duration_ms")
    let warmupMs = try nonnegativeDouble(json, "warmup_ms")
    let cooldownMs = try nonnegativeDouble(json, "cooldown_ms")
    let betweenInstancesMs = try nonnegativeDouble(json, "between_instances_ms")
    let betweenRunsMs = try nonnegativeDouble(json, "between_runs_ms")
    let minFrames = try positiveInt(json, "min_frames")
    let layout = try requiredString(json, "layout")
    let spacing = Float(try positiveDouble(json, "spacing"))
    let seedValue = try nonnegativeInt(json, "seed")
    guard let seed = UInt32(exactly: seedValue) else {
        throw ManifestError.invalidField("seed")
    }
    guard let shuffle = json["shuffle"] as? Bool else {
        throw ManifestError.invalidField("shuffle")
    }
    let declaredRunCount = try positiveInt(json, "run_count")
    guard let runObjects = json["runs"] as? [[String: Any]] else {
        throw ManifestError.invalidField("runs")
    }
    guard runObjects.count == declaredRunCount else {
        throw ManifestError.runCountMismatch(
            expected: declaredRunCount,
            actual: runObjects.count
        )
    }

    var runIds = Set<String>()
    let rows = try runObjects.map { run -> ManifestRunConfig in
        let runNumber = try positiveInt(run, "run_number")
        let runId = try requiredString(run, "run_id")
        let suiteId = try requiredString(run, "suite_id")
        guard runIds.insert(runId).inserted else {
            throw ManifestError.duplicateRunId(runId)
        }
        try validateSurfaceMode(surfaceMode, suiteId: suiteId)

        return ManifestRunConfig(
            runNumber: runNumber,
            suiteId: suiteId,
            runId: runId,
            cooldownAfterMs: betweenRunsMs,
            surfaceMode: surfaceMode,
            instancesList: instances,
            trialsPerInstance: trials,
            durationMs: durationMs,
            warmupMs: warmupMs,
            cooldownMs: cooldownMs,
            betweenInstancesMs: betweenInstancesMs,
            minFrames: minFrames,
            layout: layout,
            spacing: spacing,
            seed: seed,
            shuffle: shuffle,
            runtimeFamily: runtimeFamily,
            planId: planId,
            sourceManifest: sourceManifest,
            harnessCommit: harnessCommit,
            harnessVersion: harnessVersion,
            assetRevision: assetRevision
        )
    }

    return ManifestFile(
        schema: schema,
        planId: planId,
        deviceGroup: deviceGroup,
        cohortGroup: cohortGroup,
        runtimeFamily: runtimeFamily,
        api: api,
        mode: mode,
        surfaceMode: surfaceMode,
        rows: rows.sorted { $0.runNumber < $1.runNumber }
    )
}

private func validateSurfaceMode(_ mode: String, suiteId: String) throws {
    let upper = suiteId.uppercased()
    if upper.contains("MATERIAL") && mode != "basecolor" {
        throw ManifestError.surfaceModeMismatch(
            "\(suiteId) requires surface_mode=basecolor"
        )
    }
    if mode == "basecolor" && !upper.contains("MATERIAL") {
        throw ManifestError.surfaceModeMismatch(
            "surface_mode=basecolor requires a MATERIAL suite ID"
        )
    }
}

private func string(_ object: [String: Any], _ key: String) -> String {
    object[key] as? String ?? ""
}

private func requiredString(_ object: [String: Any], _ key: String) throws -> String {
    let value = string(object, key)
    guard !value.isEmpty else { throw ManifestError.invalidField(key) }
    return value
}

private func positiveInt(_ object: [String: Any], _ key: String) throws -> Int {
    let value = try nonnegativeInt(object, key)
    guard value > 0 else { throw ManifestError.invalidField(key) }
    return value
}

private func nonnegativeInt(_ object: [String: Any], _ key: String) throws -> Int {
    guard let number = object[key] as? NSNumber else {
        throw ManifestError.invalidField(key)
    }
    let value = number.intValue
    guard value >= 0, Double(value) == number.doubleValue else {
        throw ManifestError.invalidField(key)
    }
    return value
}

private func positiveDouble(_ object: [String: Any], _ key: String) throws -> Double {
    let value = try nonnegativeDouble(object, key)
    guard value > 0 else { throw ManifestError.invalidField(key) }
    return value
}

private func nonnegativeDouble(_ object: [String: Any], _ key: String) throws -> Double {
    guard let number = object[key] as? NSNumber else {
        throw ManifestError.invalidField(key)
    }
    let value = number.doubleValue
    guard value.isFinite, value >= 0 else {
        throw ManifestError.invalidField(key)
    }
    return value
}

private func intArray(_ object: [String: Any], _ key: String) throws -> [Int] {
    guard let values = object[key] as? [NSNumber], !values.isEmpty else {
        throw ManifestError.invalidField(key)
    }
    let result = values.map(\.intValue)
    guard result.allSatisfy({ $0 > 0 }) else {
        throw ManifestError.invalidField(key)
    }
    return result
}
